30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.samples.petclinic.util.AddressComposer;
41	import org.springframework.samples.petclinic.util.AddressNormalizer;
42	import org.springframework.samples.petclinic.util.EmailNormalizer;
43	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.servlet.http.HttpServletRequest;
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /** Header carrying the client-supplied key that makes a create idempotent. */
63	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
74	
75	    private final HttpServletRequest request;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 IdempotencyKeyRegistry idempotencyKeyRegistry,
82	                                 HttpServletRequest request) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
88	        this.request = request;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
120	        Owner alreadyCreated = idempotencyKeyRegistry.ownerIdFor(idempotencyKey)
121	            .map(this.clinicService::findOwnerById)
122	            .orElse(null);
123	        if (alreadyCreated != null) {
124	            return new ResponseEntity<>(ownerMapper.toOwnerDto(alreadyCreated), HttpStatus.OK);
125	        }
126	        HttpHeaders headers = new HttpHeaders();
127	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
128	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
129	        this.clinicService.createOwner(owner, sharesHousehold);
130	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
140	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
141	        if (currentOwner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        currentOwner.setAddressLine1(AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1()));
145	        currentOwner.setAddressLine2(AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2()));
146	        currentOwner.setAddress(AddressComposer.compose(ownerFieldsDto.getAddressLine1(),
147	            ownerFieldsDto.getAddressLine2(), ownerFieldsDto.getAddress()));
148	        currentOwner.setCity(ownerFieldsDto.getCity());
149	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
150	        currentOwner.setLastName(ownerFieldsDto.getLastName());
151	        currentOwner.setTitle(ownerFieldsDto.getTitle());
152	        currentOwner.setTelephone(TelephoneNormalizer.toE164(ownerFieldsDto.getTelephone()).orElse(null));
153	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
154	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
155	        this.clinicService.saveOwner(currentOwner);
156	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Transactional
161	    @Override
162	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
163	        Owner owner = this.clinicService.findOwnerById(ownerId);
164	        if (owner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        this.clinicService.deleteOwner(owner);
168	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
174	        Owner owner = this.clinicService.findOwnerById(ownerId);
175	        if (owner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        HttpHeaders headers = new HttpHeaders();
179	        Pet pet = petMapper.toPet(petFieldsDto);
180	        owner.setId(ownerId);
181	        pet.setOwner(owner);
182	        pet.getType().setName(null);
183	        this.clinicService.savePet(pet);
184	        PetDto petDto = petMapper.toPetDto(pet);
185	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
186	            .buildAndExpand(pet.getId()).toUri());
187	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
193	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
194	        if (currentOwner != null) {
195	            Pet currentPet = this.clinicService.findPetById(petId);
196	            if (currentPet != null) {
197	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
198	                currentPet.setName(petFieldsDto.getName());
199	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
200	                this.clinicService.savePet(currentPet);
201	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
202	            }
203	        }
204	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
210	        HttpHeaders headers = new HttpHeaders();
211	        Visit visit = visitMapper.toVisit(visitFieldsDto);
212	        Pet pet = new Pet();
213	        pet.setId(petId);
214	        visit.setPet(pet);
215	        this.clinicService.saveVisit(visit);
216	        VisitDto visitDto = visitMapper.toVisitDto(visit);
217	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
218	            .buildAndExpand(visit.getId()).toUri());
219	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
220	    }
221	
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
226	        Owner owner = this.clinicService.findOwnerById(ownerId);
227	        if (owner != null) {
228	            Pet pet = owner.getPet(petId);
229	            if (pet != null) {
230	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
231	            }
232	        }
233	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	    }
235	}
