265	    protected Set<Pet> getPetsInternal() {
266	        if (this.pets == null) {
267	            this.pets = new HashSet<>();
268	        }
269	        return this.pets;
270	    }
271	
272	    protected void setPetsInternal(Set<Pet> pets) {
273	        this.pets = pets;
274	    }
275	
276	    public List<Pet> getPets() {
277	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
278	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
279	        return Collections.unmodifiableList(sortedPets);
280	    }
281	
282	    public void setPets(List<Pet> pets) {
283	        this.pets = new HashSet<>(pets);
284	    }
285	
286	    public void addPet(Pet pet) {
287	        getPetsInternal().add(pet);
288	        pet.setOwner(this);
289	    }
290	
291	    /**
292	     * Return the Pet with the given name, or null if none found for this Owner.
293	     *
294	     * @param name to test
295	     * @return true if pet name is already in use
296	     */
297	    public Pet getPet(String name) {
298	        return getPet(name, false);
299	    }
300	
301	    /**
302	     * Return the Pet with the given name, or null if none found for this Owner.
303	     *
304	     * @param name to test
305	     * @return true if pet name is already in use
306	     */
307	    public Pet getPet(String name, boolean ignoreNew) {
308	        name = name.toLowerCase();
309	        for (Pet pet : getPetsInternal()) {
310	            if (!ignoreNew || !pet.isNew()) {
311	                String compName = pet.getName();
312	                compName = compName.toLowerCase();
313	                if (compName.equals(name)) {
314	                    return pet;
315	                }
316	            }
317	        }
318	        return null;
319	    }
320	
321	    public Pet getPet(Integer petId) {
322	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
323	    }
324	
325	    @Override
326	    public String toString() {
327	        return new ToStringCreator(this)
328	
329	            .append("id", this.getId())
330	            .append("new", this.isNew())
331	            .append("lastName", this.getLastName())
332	            .append("firstName", this.getFirstName())
333	            .append("address", this.address)
334	            .append("city", this.city)
335	            .append("telephone", this.telephone)
336	            .toString();
337	    }
338	}
