17	package org.springframework.samples.petclinic.audit;
18	
19	import java.util.concurrent.atomic.AtomicLong;
20	
21	import org.slf4j.Logger;
22	import org.slf4j.LoggerFactory;
23	import org.springframework.samples.petclinic.model.Owner;
24	import org.springframework.samples.petclinic.util.OwnerMembership;
25	import org.springframework.samples.petclinic.util.OwnerSegment;
26	import org.springframework.stereotype.Component;
27	
28	import tools.jackson.databind.ObjectMapper;
29	import tools.jackson.databind.json.JsonMapper;
30	
31	/**
32	 * Emits audit records for owner lifecycle events to the dedicated {@code AUDIT} logger,
33	 * keeping audit-trail concerns out of the business logic that triggers them.
34	 */
35	@Component
36	public class OwnerAuditLogger {
37	
38	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
39	
40	    private static final ObjectMapper EVENT_MAPPER = JsonMapper.builder().build();
41	
42	    /** Source of the monotonically increasing sequence number carried by each event. */
43	    private final AtomicLong sequence = new AtomicLong();
44	
45	    /**
46	     * Record that an owner was successfully created. Emits both the human-readable
47	     * audit line and an immutable structured {@link OwnerCreatedEvent} as JSON, so
48	     * downstream consumers can process the event without parsing the free-form line.
49	     *
50	     * @param owner the persisted owner (with its generated id) to audit
51	     */
52	    public void ownerCreated(Owner owner) {
53	        AUDIT.info(
54	            "Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
55	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel(owner));
56	        OwnerCreatedEvent event = new OwnerCreatedEvent(sequence.incrementAndGet(), owner.getId(),
57	            primaryIdentifier(owner), membershipLevel(owner), OwnerSegment.of(owner));
58	        AUDIT.info(EVENT_MAPPER.writeValueAsString(event));
59	    }
60	
61	    /**
62	     * The owner's current primary identifier: their unified {@code memberId}.
63	     */
64	    private static String primaryIdentifier(Owner owner) {
65	        return owner.getMemberId();
66	    }
67	
68	    private static int membershipLevel(Owner owner) {
69	        return OwnerMembership.level(owner);
70	    }
71	}
