253	    /**
254	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
255	     * already reached this many owners is rejected as a conflict.
256	     */
257	    static final int MAX_OWNERS_PER_CITY = 50;
258	
259	    /**
260	     * Number of owners that must already exist in a city before a new owner registered there is
261	     * flagged with a capacity warning. Once the count already recorded for the city reaches this
262	     * value (but is still below {@link #MAX_OWNERS_PER_CITY}), the new owner carries
263	     * {@code capacityWarning == true} to signal that the city is approaching its capacity limit.
264	     */
265	    static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
266	
267	    /**
268	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
269	     * already reached this many registrations is rejected as a rate-limit violation.
270	     */
271	    static final int MAX_OWNERS_PER_DAY = 100;
272	
273	    /**
274	     * Number of owners that must already have registered on a day before a new registration is
275	     * flagged with a bulk-signup warning. Once the count already recorded for the day exceeds this
276	     * value, the new owner carries {@code bulkSignupWarning == true}.
277	     */
278	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
279	
280	    @Override
281	    @Transactional
282	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
283	        if (DisposableEmailDomains.isDisposable(owner.getEmail())) {
284	            throw new DisposableEmailDomainException(owner.getEmail());
285	        }
286	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
287	        rejectIdentityCollision(owner);
288	        List<Owner> householdMembers = findHouseholdMembers(owner);
289	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
290	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
291	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
292	        }
293	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
294	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
295	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
296	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
297	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
298	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
299	        }
300	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
301	        flagPossibleDuplicate(owner, sharesHousehold);
302	        owner.setNamesakeCount(countNamesakes(owner));
303	        owner.setHouseholdSize(householdMembers.size() + 1);
304	        owner.setMembershipLevel(OwnerMembership.cappedLevel(owner, householdMembers));
305	        owner.setMemberId(assignMemberId(owner));
306	        ownerRepository.save(owner);
307	        ownerAuditLogger.ownerCreated(owner);
308	        welcomeNotifier.welcome(owner);
309	        return owner.getHouseholdId();
310	    }
311	
312	    /**
313	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
314	     * another active owner. Because the telephone is part of the key, only an existing owner sharing
315	     * every key component (normalized telephone, lower-cased email and the last name's Soundex code)
316	     * is a hard duplicate; telephone equality remains a prerequisite, so it prefilters the candidates.
317	     */
318	    private void rejectIdentityCollision(Owner owner) {
319	        String identityKey = OwnerIdentityKey.of(owner);
320	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
321	            .filter(ClinicServiceImpl::isActive)
322	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
323	        if (collides) {
324	            throw new DuplicateOwnerException(identityKey);
325	        }
326	    }
327	
328	    /**
329	     * Whether an existing owner is still active, i.e. has not been soft-deleted. Soft-deleted owners
330	     * are retained for history but ignored by the create-time duplicate and identity checks.
331	     */
332	    private static boolean isActive(Owner owner) {
333	        return !Boolean.TRUE.equals(owner.getDeleted());
334	    }
335	
336	    /**
337	     * Build the new owner's {@code memberId} and de-duplicate it against existing owners. The base
338	     * id is derived from the owner's locality, registration date, telephone and last name; if it
339	     * already belongs to another owner it is suffixed with the smallest {@code "-<n>"} (n &gt;= 2)
340	     * that is still free.
341	     */
342	    private String assignMemberId(Owner owner) {
343	        String baseId = MemberIdGenerator.format(
344	            IdentityRegionCode.v2(LocalityResolver.resolve(owner.getCity(), owner.getPostcode())),
345	            owner.getRegistrationDate(), owner.getTelephone(), owner.getLastName());
346	        Set<String> takenIds = ownerRepository.findByMemberIdStartingWith(baseId).stream()
347	            .map(Owner::getMemberId)
348	            .collect(Collectors.toSet());
349	        return MemberIdGenerator.deduplicate(baseId, takenIds::contains);
350	    }
351	
352	    /**
353	     * Flag the new owner as a possible (soft) duplicate of an existing owner whose identity key
354	     * <em>differs</em> but whose last name shares the same Soundex code and whose postcode is equal.
355	     * The new owner is still created; {@code possibleDuplicate} is set to whether such a match exists
356	     * and {@code possibleDuplicateOf} to the matching owner's id (the lowest when several match), or
357	     * {@code null} when there is no match.
358	     *
359	     * <p>An owner that explicitly declares {@code sharesHousehold} is a <em>declared</em> household
360	     * member rather than a suspected duplicate, so it is never flagged.
361	     */
362	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
363	        Owner match = sharesHousehold ? null : findSoftMatchCandidates(owner).stream()
364	            .min(Comparator.comparingInt(Owner::getId))
365	            .orElse(null);
366	        owner.setPossibleDuplicate(match != null);
367	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
368	    }
369	
370	    /**
371	     * Find the existing active owners that are a soft match for the new owner: those sharing its
372	     * postcode and its last name's {@link org.springframework.samples.petclinic.util.Soundex Soundex}
373	     * code, but deriving a <em>different</em> {@link OwnerIdentityKey identity key} (an equal key is a
374	     * hard duplicate, rejected earlier). An owner without a postcode has no soft-match candidates.
375	     */
376	    private List<Owner> findSoftMatchCandidates(Owner owner) {
377	        if (owner.getPostcode() == null) {
378	            return List.of();
379	        }
380	        String soundex = Soundex.encode(owner.getLastName());
381	        String identityKey = OwnerIdentityKey.of(owner);
382	        return ownerRepository.findByPostcode(owner.getPostcode()).stream()
383	            .filter(ClinicServiceImpl::isActive)
384	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
385	            .filter(existing -> !identityKey.equals(OwnerIdentityKey.of(existing)))
386	            .toList();
387	    }
388	
389	    @Override
390	    @Transactional
391	    public void saveOwner(Owner owner) throws DataAccessException {
392	        ownerRepository.save(owner);
393	    }
394	
395	    /**
396	     * Count the owners that already exist sharing this owner's first name and last name, compared
397	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
398	     */
399	    private int countNamesakes(Owner owner) {
400	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
