7	/**
8	 * Validates that an owner's postcode, when present, is valid for the owner's city per the
9	 * fixed region ranges (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
10	 * region accepts any 4-digit postcode. An absent postcode is always accepted.
11	 */
12	@Target({ ElementType.TYPE })
13	@Retention(RetentionPolicy.RUNTIME)
14	@Constraint(validatedBy = ValidPostcodeForCityValidator.class)
15	@Documented
16	public @interface ValidPostcodeForCity {
17	
18	    String message() default "Postcode is not valid for the city's region";
19	
20	    Class<?>[] groups() default {};
21	
22	    Class<? extends Payload>[] payload() default {};
23	}
