2	
3	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
4	
5	import jakarta.validation.ConstraintValidator;
6	import jakarta.validation.ConstraintValidatorContext;
7	
8	/**
9	 * Enforces {@link ValidAddressForm}: the owner must carry an address in at least one form, i.e. a
10	 * non-blank {@code addressLine1} or a non-blank flat {@code address}. When neither is present the
11	 * violation is reported against {@code addressLine1}.
12	 */
13	public class ValidAddressFormValidator implements ConstraintValidator<ValidAddressForm, OwnerFieldsDto> {
14	
15	    @Override
16	    public boolean isValid(OwnerFieldsDto owner, ConstraintValidatorContext context) {
17	        if (owner == null) {
18	            return true;
19	        }
20	        if (hasText(owner.getAddressLine1()) || hasText(owner.getAddress())) {
21	            return true;
22	        }
23	        context.disableDefaultConstraintViolation();
24	        context.buildConstraintViolationWithTemplate(context.getDefaultConstraintMessageTemplate())
25	            .addPropertyNode("addressLine1")
26	            .addConstraintViolation();
27	        return false;
28	    }
29	
30	    private static boolean hasText(String value) {
31	        return value != null && !value.isBlank();
32	    }
