202	    @ExceptionHandler(DataIntegrityViolationException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
205	        logger.warn("Data integrity violation at {} {}: {}",
206	            request.getMethod(),
207	            request.getRequestURI(),
208	            e.getMessage());
209	        logger.debug("Data integrity violation stacktrace", e);
210	        HttpStatus status = HttpStatus.NOT_FOUND;
211	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
212	        return ResponseEntity.status(status).body(detail);
213	    }
