16	package org.springframework.samples.petclinic.model;
17	
18	import jakarta.persistence.GeneratedValue;
19	import jakarta.persistence.GenerationType;
20	import jakarta.persistence.Id;
21	import jakarta.persistence.MappedSuperclass;
22	
23	import com.fasterxml.jackson.annotation.JsonIgnore;
24	
25	/**
26	 * Simple JavaBean domain object with an id property. Used as a base class for objects needing this property.
27	 *
28	 * @author Ken Krebs
29	 * @author Juergen Hoeller
30	 */
31	@MappedSuperclass
32	public class BaseEntity {
33	    @Id
34	    @GeneratedValue(strategy = GenerationType.IDENTITY)
35	    protected Integer id;
36	
37	    public Integer getId() {
38	        return id;
39	    }
40	
41	    public void setId(Integer id) {
42	        this.id = id;
43	    }
44	    @JsonIgnore
45	    public boolean isNew() {
46	        return this.id == null;
47	    }
48	
49	}
